from lib import *
S = SS('t14')
steps = [
    step("先查后插 vs 先插唯一键:200 个 key,每个 key 同时到达 8 个重复请求(8 个线程过屏障后同时执行)。先 SELECT 看有没有、没有再做业务并插记录:1600 个请求里业务实际执行了 1590 次,200 个 key 全部被执行了多次,多执行 1390 次——两个请求都查到“没有”就各自去做业务,唯一键只在最后插记录时才冲突,管得住记录管不住业务。先 INSERT 唯一键、抢到的那个请求在同一个事务里执行业务:业务执行 200 次,正好每个 key 一次,多执行 0。", t=tl(S(1)), mark=lidx(S(1), '先 SELECT 看有没有'), done=lidx(S(1), '先 INSERT 唯一键'), b=bars([['先查后插:业务执行次数', 1590, '1590(应为 200)'], ['先插唯一键:业务执行次数', 200, '200']], 1600, mark=[0], done=[1]), kv=KV([['先查后插', '1600 个请求执行了 1590 次'], ['先插唯一键', '执行 200 次,每个 key 一次'], ['原因', '唯一键要在做业务之前占位']], ['原因'])),
    step("去重记录和业务必须在同一个本地事务里。每个 key 的第二步有 20% 概率失败,客户端失败后最多重试 6 次,1000 个 key:去重记录先单独提交、再做业务,799 个恰好执行 1 次、201 个一次都没执行——业务失败后重试被当成重复拒绝,这笔业务永远丢了;业务先单独提交、再记去重,790 个恰好 1 次、210 个被执行了多次——记去重失败后重试又执行一遍;去重记录和业务在同一个事务里,1000 个全部恰好执行 1 次。", t=tl(S(2)), mark=lidx(S(2), '去重记录先单独提交', '业务先单独提交'), done=lidx(S(2), '去重记录和业务在同一个事务里'), b=bars([['去重先提交:丢的 key', 201, '201'], ['业务先提交:重复的 key', 210, '210'], ['同一个事务:恰好 1 次的 key', 1000, '1000']], 1000, mark=[0, 1], done=[2]), kv=KV([['去重先提交', '业务失败后重试被拒,丢 201'], ['业务先提交', '记去重失败后重试,重复 210'], ['同一个事务', '1000 个全部恰好 1 次']], ['同一个事务'])),
    step("状态型幂等键:第一个请求先插一行 PROCESSING,处理完改成 DONE 并保存结果。第一个请求耗时 307 ms;100 ms 时到达的重复请求遇到“处理中”直接返回 409(1 ms);500 ms 时再来的重复请求拿到保存的结果“扣款成功#s1”(1 ms)。另一种策略是重复请求等第一个处理完再返回:重复请求等了 210 ms 拿到同一个结果。payments 里 s1、s2 各只执行了 1 次。如果第一个请求在 PROCESSING 时被杀,这一行会一直留着,要靠租约:0 秒时租约未过期,重复请求只能等;1.2 秒后用 UPDATE ... WHERE locked_until < now() 抢占,抢到 1 行的才能重新执行。", t=tl(S(3)), mark=lidx(S(3), '409 正在处理中', '租约未过期=True'), done=lidx(S(3), '返回已保存的结果', '抢到的行数 = 1'), b=bars([['第一个请求耗时 ms', 307, '307'], ['重复请求(遇到处理中)返回 409 ms', 1, '1'], ['重复请求(等待)耗时 ms', 210, '210']], 310, cur=[0], done=[1], mark=[2]), kv=KV([['PROCESSING', '重复请求 409 或等待'], ['DONE', '直接返回保存的结果'], ['进程被杀', '靠租约过期后 UPDATE 抢占']], ['进程被杀'])),
    step("去重表的成本。单行插入(各 3000 次中位数):只插 payments 97 µs,只插 dedup 96 µs,几乎一样。dedup 里 30 万个 key 占 13.5 MiB,平均每行约 47 字节。按保留期 60 分钟分批清理(每批 5000 行),15 万个过期 key 用 1.40 s 清完,同时插入照常进行:p99 1280 µs(没清理时 1561 µs),中位数 169 µs 到 235 µs。单次测量、样本只有两三千次,p99 的高低方向重跑会变,不能据此断言清理对写入延迟的影响。保留期必须比客户端的最长重试窗口长:保留期 60 分钟、重试窗口 2 小时时,2 小时前处理过的 late-1 被清掉,它的重试 INSERT 成功,被当成新请求,业务再执行一次。", t=tl(S(4)), mark=lidx(S(4), '保留期(60 分钟)比客户端'), done=lidx(S(4), '单行插入', '按保留期 60 分钟分批清理'), b=bars([['插 payments µs', 97, '97'], ['插 dedup µs', 96, '96'], ['30 万个 key 每行字节', 47, '47'], ['清理 15 万行用时 s', 1.40, '1.40']], 100, cur=[0, 1, 2], done=[3]), kv=KV([['插入', '和普通插入几乎一样'], ['体积', '30 万个 key 13.5 MiB'], ['保留期', '必须长于最长重试窗口']], ['保留期'])),
    step("三种“先占位”的写法:INSERT IGNORE 看 rowcount、INSERT ... ON DUPLICATE KEY UPDATE 看 rowcount、直接 INSERT 捕获唯一键异常;4 个线程各 5000 次请求,key 从 2500 个里随机选(约一半是重复)。三种写法的业务执行次数都是 2499,正好等于去重表里不同的 key 数 2499,payments 也是 2499 行。吞吐 3 轮中位数分别是 25750、23617、24481 请求/秒,范围 20975 到 27276、22259 到 25552、24209 到 25731,彼此落在波动范围之内,没有明确的高低。选哪种写法主要是代码风格的问题,保证正确的是“只有抢到唯一键的那个请求才执行业务”。", t=tl(S(5)), mark=lidx(S(5), '直接 INSERT,捕获唯一键异常'), done=lidx(S(5), 'INSERT IGNORE', 'ON DUPLICATE KEY UPDATE'), b=bars([['INSERT IGNORE 请求/秒', 25750, '25750'], ['ODKU 请求/秒', 23617, '23617'], ['捕获异常 请求/秒', 24481, '24481']], 27000, cur=[0, 1, 2]), kv=KV([['业务执行次数', '三种都是 2499 = 不同 key 数'], ['吞吐', '差别在波动范围内'], ['关键', '抢到唯一键才执行业务']], ['关键'])),
]
A = mkartt('t14', 14, '分布式事务,幂等,幂等键,去重表,MySQL,唯一索引,真实验证,动画演示',
    '实测幂等键的去重表设计:200 个 key 各 8 个并发重复请求,先查后插让业务执行了 1590 次,先插唯一键正好 200 次;去重记录与业务不在同一个事务里,1000 个 key 里丢 201 个或重复 210 个,同一个事务 0;状态型幂等键与租约;去重表 30 万 key 13.5 MiB;保留期短于重试窗口会再执行一次。',
    '“重复提交不重复执行”靠幂等键和去重表。可是先查后插能不能防住并发?去重记录和业务要放在哪里才不丢不重?请求还在处理时重复到达怎么办?去重表要保留多久?这篇用真实的 MySQL 把每个问题量出来。',
    [('1590 vs 200', '200 个 key 各 8 个并发重复请求:先查后插与先插唯一键的业务执行次数'), ('201 / 210 / 0', '去重记录先提交丢的 key 数 / 业务先提交重复的 key 数 / 同一个事务里的错误数(1000 个 key、20% 失败)'), ('13.5 MiB', '去重表存 30 万个 key 占用的空间(每行约 47 字节)')],
    [('唯一键要在业务之前占位', '<p>先查后插时,两个并发请求都查到“没有”就各自执行业务;先插唯一键,抢到的那个请求才能做业务。</p>'),
     ('同一个事务', '<p>去重记录和业务分开提交,崩溃时要么业务丢失(记录先提交),要么重复执行(业务先提交);放在同一个本地事务里才既不丢也不重复。</p>'),
     ('状态型幂等键', '<p>PROCESSING 行占位、DONE 行保存结果:处理中遇到重复请求返回 409 或等待,处理完直接返回保存的结果;进程崩溃留下的 PROCESSING 靠租约过期后抢占。</p>'),
     ('去重表的成本', '<p>插入与普通插入几乎一样,每行约 47 字节;保留期必须长于客户端的最长重试窗口,否则被清掉的 key 的重试会被当成新请求。</p>'),
     ('三种占位写法', '<p>INSERT IGNORE、ON DUPLICATE KEY UPDATE、捕获唯一键异常都是正确的,吞吐在波动范围内没有明确高低。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例(payments、dedup、idem 三张表),客户端 PyMySQL,并发用线程 + 屏障;第二节的 20% 失败是在代码里用固定种子的随机数抛错;吞吐是 3 轮交替的中位数,每轮 4 个线程各 5000 次',
     '没有验证:分布式环境下多个服务实例共用去重表的跨库 / 跨机房情形;用 Redis 做去重(SETNX)与 MySQL 唯一键的差别;幂等键的生成方式(客户端 UUID、业务单号、消息 offset)的比较;去重表分区 / 按时间分表来清理;租约时长怎么取;保留期的取值只是示例,没有对应真实业务的重试窗口'],
    '幂等键')
